// Format and validate incoming lead data from webhook
const inputData = $input.first().json;

try {
  // Extract lead information from form submission
  // Adjust field names based on your form structure
  const formattedLead = {
    name: inputData.name || inputData.full_name || inputData.firstName + ' ' + (inputData.lastName || '') || 'Unknown',
    email: inputData.email || inputData.email_address || '',
    company: inputData.company || inputData.company_name || inputData.organization || '',
    phone: inputData.phone || inputData.phone_number || '',
    message: inputData.message || inputData.inquiry || inputData.comments || '',
    budget: inputData.budget || inputData.budget_range || '',
    timeline: inputData.timeline || inputData.timeframe || inputData.urgency || '',
    source: inputData.source || inputData.referral_source || inputData.how_did_you_hear || '',
    services: inputData.services || inputData.service_interest || inputData.what_do_you_need || '',
    submittedAt: new Date().toISOString(),
    rawData: JSON.stringify(inputData)
  };

  // Build context string for AI scoring
  const leadContext = `
Name: ${formattedLead.name}
Email: ${formattedLead.email}
Company: ${formattedLead.company}
Phone: ${formattedLead.phone}
Message/Inquiry: ${formattedLead.message}
Budget: ${formattedLead.budget}
Timeline: ${formattedLead.timeline}
Source: ${formattedLead.source}
Services Interested In: ${formattedLead.services}
  `.trim();

  return [{
    json: {
      ...formattedLead,
      leadContext: leadContext
    }
  }];

} catch (error) {
  return [{
    json: {
      error: true,
      message: 'Failed to format lead data: ' + error.message,
      rawData: inputData
    }
  }];
}

// Parse the AI scoring response and extract structured data
const inputData = $input.first().json.output[0].content[0].text;
const leadData = $('Format Lead Data').first().json;

try {
  // Get the AI response content
  let aiResponse = inputData.message?.content || inputData.content || inputData.text || inputData;

  // Parse if it's a string
  if (typeof aiResponse === 'string') {
    // Remove any markdown code blocks if present
    aiResponse = aiResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    aiResponse = JSON.parse(aiResponse);
  }

  // Extract and validate the score
  const score = parseInt(aiResponse.score) || 5;
  const isHighIntent = score >= 7;

  // Combine lead data with scoring results
  const scoredLead = {
    // Original lead info
    name: leadData.name,
    email: leadData.email,
    company: leadData.company,
    phone: leadData.phone,
    message: leadData.message,
    budget: leadData.budget,
    timeline: leadData.timeline,
    source: leadData.source,
    services: leadData.services,
    submittedAt: leadData.submittedAt,

    // AI scoring results
    intentScore: score,
    intentLevel: aiResponse.intent_level || (isHighIntent ? 'high' : 'low'),
    reasoning: aiResponse.reasoning || 'No reasoning provided',
    buyingSignals: Array.isArray(aiResponse.buying_signals) ? aiResponse.buying_signals.join(', ') : '',
    redFlags: Array.isArray(aiResponse.red_flags) ? aiResponse.red_flags.join(', ') : '',
    recommendedAction: aiResponse.recommended_action || '',
    priority: aiResponse.priority || 'normal',

    // Routing flag
    isHighIntent: isHighIntent
  };

  return [{ json: scoredLead }];

} catch (error) {
  // Return with default low score on error
  return [{
    json: {
      ...leadData,
      intentScore: 5,
      intentLevel: 'medium',
      reasoning: 'Error parsing AI response: ' + error.message,
      buyingSignals: '',
      redFlags: '',
      recommendedAction: 'Manual review required',
      priority: 'normal',
      isHighIntent: false,
      parseError: true
    }
  }];
}

